class TopNTest(unittest.TestCase):
    def test_most_frequent_first(self):
        self.assertEqual(top_n("b a b c b a", 2), [("b", 3), ("a", 2)])

    def test_ties_in_alphabetical_order(self):
        self.assertEqual(top_n("pear apple fig apple pear fig", 3),
                         [("apple", 2), ("fig", 2), ("pear", 2)])

    def test_n_larger_than_word_count(self):
        self.assertEqual(top_n("Hello, hello world.", 10), [("hello", 2), ("world", 1)])

    def test_zero_and_empty(self):
        self.assertEqual(top_n("a b", 0), [])
        self.assertEqual(top_n("", 3), [])

def test_top_option_limits_output(self):
    status, out = self.run_cli("the cat. The dog. the end cat", "--top", "2")
    self.assertEqual(status, 0)
    self.assertEqual(out.splitlines(), ["the 3", "cat 2"])

def test_top_option_invalid_value(self):
    self.assertEqual(main(["--top", "x", "file.txt"]), 2)

def test_usage_error(self):
    self.assertEqual(main([]), 2)
